import{_ as e,o as r,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"HJ7 取近似值","description":"描述 写出一个程序，接受一个正浮点数值，输出该数值的近似整数值。如果小数点后数值大于等于 0.5 ,向上取整；小于 0.5 ，则向下取整。 数据范围：保证输入的数字在 32 位浮点数范围内 输入描述： 输入一个正浮点数值 输出描述： 输出该数值的近似整数值 示例1 输入： 5.5。","frontmatter":{"title":"HJ7 取近似值","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 写出一个程序，接受一个正浮点数值，输出该数值的近似整数值。如果小数点后数值大于等于 0.5 ,向上取整；小于 0.5 ，则向下取整。 数据范围：保证输入的数字在 32 位浮点数范围内 输入描述： 输入一个正浮点数值 输出描述： 输出该数值的近似整数值 示例1 输入： 5.5。","sidebarWeight":41,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为入门题/HJ7 取近似值.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ7 取近似值.md","filePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ7 取近似值.md"}'),a={name:"posts/前端面试与实战/03-算法训练/华为入门题/HJ7 取近似值.md"};function s(u,t,i,d,_,p){return r(),o("div",null,[...t[0]||(t[0]=[n('<div><h1 id="hj7-取近似值" tabindex="-1">HJ7 取近似值 <a class="header-anchor" href="#hj7-取近似值" aria-label="Permalink to &quot;HJ7 取近似值&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ7 取近似值”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 写出一个程序，接受一个正浮点数值，输出该数值的近似整数值。如果小数点后数值大于等于 0.5 ,向上取整；小于 0.5 ，则向下取整。 数据范围：保证输入的数字在 32 位浮点数范围内 <strong>输入描述：</strong> 输入一个正浮点数值 <strong>输出描述：</strong> 输出该数值的近似整数值 <strong>示例1</strong> 输入： 5.5 ==复制== 输出： 6 ==复制== 说明： 0.5&gt;=0.5，所以5.5需要向上取整为6 <strong>示例2</strong> 输入： 2.499 ==复制== 输出： 2 ==复制== 说明： 0.499&lt;0.5，2.499向下取整为2</p></blockquote><p><strong>只考虑正数</strong> def round_number(number): return int(number + 0.5)</p><p><strong>考虑正数和负数</strong> def round_number(number): &quot;&quot;&quot; 四舍五入方法，考虑正负数。 :param number: 输入的浮点数 :return: 四舍五入后的整数 &quot;&quot;&quot; if number &gt;= 0: return int(number + 0.5) else: return int(number - 0.5)</p><h1 id="从用户那里获取输入" tabindex="-1">从用户那里获取输入 <a class="header-anchor" href="#从用户那里获取输入" aria-label="Permalink to &quot;从用户那里获取输入&quot;">​</a></h1><p>input_number = float(input(&quot;请输入一个浮点数：&quot;))</p><h1 id="调用四舍五入函数-并打印结果" tabindex="-1">调用四舍五入函数，并打印结果 <a class="header-anchor" href="#调用四舍五入函数-并打印结果" aria-label="Permalink to &quot;调用四舍五入函数，并打印结果&quot;">​</a></h1><p>rounded_number = round_number(input_number) print(&quot;四舍五入的结果是：&quot;, rounded_number)</p></div>',1)])])}const c=e(a,[["render",s]]);export{m as __pageData,c as default};
